import c4d

def main():
    global SourceTag, CopyTag

    if not SourceTag or not CopyTag:
        return
    if not isinstance(SourceTag, c4d.VariableTag) and not isinstance(SourceTag, c4d.SelectionTag):
        # Turns the XPresso Node yellow.
        raise Exception('need a Vertex Map or a Selection SourceTag, but got ' + SourceTag.GetTypeName())
    elif not isinstance(CopyTag, c4d.VariableTag) and not isinstance(CopyTag, c4d.SelectionTag):
        # Turns the XPresso Node yellow.
        raise Exception('need a Vertex Map or a Selection SourceTag, but got ' + SourceTag.GetTypeName())

    if SourceTag.GetType() != CopyTag.GetType():
        raise Exception('both tags need to be of the same type')

    if SourceTag.GetType() == c4d.Tvertexmap:
        if SourceTag.GetDataCount() != CopyTag.GetDataCount():
            print("The two tags have different Count values")
            return
        values = SourceTag.GetAllHighlevelData()
        CopyTag.SetAllHighlevelData(values)

    else:
        sel = SourceTag.GetBaseSelect()
        copySel = CopyTag.GetBaseSelect()
        sel.CopyTo(copySel)

